// All runs the plan in exactly TWO round trips. Distinct parent keys are
// de-duplicated before the second, so a thousand rows pointing at three
// orgs fetch three orgs.
func (p WorkerSampleWithWorkerQuery) All(ctx context.Context, ex runtime.Executor) ([]WorkerSampleWithWorkerRow, error) {
	parents, err := p.q.All(ctx, ex, nil)
	if err != nil {
		return nil, err
	}
	if len(parents) == 0 {
		return nil, nil
	}
	out := make([]WorkerSampleWithWorkerRow, len(parents))
	seen := make(map[string]bool, len(parents))
	ids := make([]string, 0, len(parents))
	for i, r := range parents {
		out[i] = WorkerSampleWithWorkerRow{Row: r}
		key := r.WorkerID
		if !seen[key] {
			seen[key] = true
			ids = append(ids, key)
		}
	}
	if len(ids) == 0 {
		return out, nil
	}
	targets, err := worker.New().Unordered().
		Where(worker.ID.In(ids...)).
		Limit(int64(len(ids))).
		All(ctx, ex, nil)
	if err != nil {
		return nil, err
	}
	by := make(map[string]int, len(targets))
	for i := range targets {
		by[targets[i].ID] = i
	}
	for i := range out {
		key := out[i].Row.WorkerID
		j, ok := by[key]
		if !ok {
			// A foreign key pointing at a row that is not there. The database
			// forbids it, so reaching this means the constraint was dropped.
			return nil, fmt.Errorf("storm: %s references a missing %s row", "worker_samples", "workers")
		}
		out[i].Worker = targets[j]
	}
	return out, nil
}
